import re, json
# Parse issues page
html = open('/root/.local/share/opencode/tool-output/tool_f5c7b89de002slwC8f2hYQ8eaB').read()
matches = re.findall(r'<script type=\"application/json\" data-target=\"react-app.embeddedData\">(.*?)</script>', html, re.DOTALL)
for m in matches:
    try:
        data = json.loads(m)
        # Look for issue count
        print('Payload keys:', list(data.get('payload', {}).keys())[:30])
        # Check if there are issues counts
        for k, v in data.get('payload', {}).items():
            if isinstance(v, dict) and 'issueCount' in str(v):
                print('Potential issueCount in key:', k)
            if isinstance(v, int) and v in [20, 21, 22, 23, 24, 25]:
                print('Potential int count:', k, v)
        # Try to find open issues count
        if 'openIssues' in str(data):
            print('openIssues found in data')
    except Exception as e:
        print('Error:', e)
"

