            # Find all keys with counts
            for k, v in data.items() if isinstance(data, dict) else []:
                pass
            if isinstance(data, dict) and 'payload' in data:
                payload = data['payload']
                if isinstance(payload, dict):
                    for pk, pv in payload.items():
                        if isinstance(pv, (int, float, str)) and any(x in str(pk).lower() for x in ['issue', 'pull', 'count', 'open']):
                            print(pk, pv)
                        if isinstance(pv, dict):
                            for sk, sv in pv.items():
                                if isinstance(sv, (int, float, str)) and any(x in str(sk).lower() for x in ['issue', 'pull', 'count', 'open']):
                                    print(pk, sk, sv)
    except Exception as e:
        pass
"

