    try:
        data = json.loads(s)
        # Check if it contains issue data
        if isinstance(data, dict):
            text = json.dumps(data)
            if 'issue' in text.lower() or 'pr' in text.lower() or 'pull' in text.lower():
                # Look for numbers 20-30
                for num in range(20, 30):
                    if str(num) in text:
                        print(f'Script {i} contains {num}')
                        # Print a snippet around the number
                        idx = text.find(str(num))
                        print('Snippet:', text[max(0,idx-50):idx+50])
                        break
    except:
        pass
"

